import json
for sid in ['S-P1-page1-010','S-P1-page1-011']:
    d=json.load(open(sid+'.json'))
    print('=====', sid, 'step', d['step_index'])
    for e in d['elements']:
        s=(e.get('selector') or '')
        if 'qty' not in s and 'line-1' not in s:
            continue
        vb=e.get('visible_box')
        box = ('%.0f,%.0f %.0fx%.0f' % (vb['x'],vb['y'],vb['w'],vb['h'])) if vb else 'no-vbox'
        a=e.get('a11y') or {}
        print('%7s %-6s role=%-9s name=%r text=%r sel=%-30s box=%-16s vis=%s a11y=%s' % (e['id'], e['tag'], str(e['role']), (e.get('name') or '')[:40], (e.get('text') or '')[:40], s[:30], box, e['visible'], json.dumps({k:a.get(k) for k in ('name_source','focusable')}, ensure_ascii=False)))
    # order button
    for e in d['elements']:
        if e.get('selector')=='#order-btn':
            vb=e.get('visible_box')
            print('   order-btn text=', repr(e['text']), 'box=', vb)
