import json, glob
seen={}
for f in sorted(glob.glob('S-P1-page1-0*.json')):
    d=json.load(open(f))
    for e in d['elements']:
        a=e.get('a11y') or {}
        if not e.get('visible'): continue
        if not e.get('interactive'): continue
        nm=(e.get('name') or '').strip()
        tx=(e.get('text') or '').strip()
        if nm=='' and tx=='':
            key=(e.get('selector') or '')+'|'+e['tag']
            seen.setdefault(key, []).append((f.replace('S-P1-page1-',''), e['id'], a.get('name_source'), e.get('visible_box')))
for k,v in seen.items():
    print(k, '->', v[0][0], v[0][1], 'name_source=', v[0][2], 'box=', v[0][3], 'count=', len(v))
